"use client";

import { useEffect, useRef, useState } from 'react';
import gsap from 'gsap';
import { siteConfig } from '@/data/site-config';

interface IntroProps {
  onComplete: () => void;
}

export default function IntroScene({ onComplete }: IntroProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const text1Ref = useRef<HTMLHeadingElement>(null);
  const text2Ref = useRef<HTMLHeadingElement>(null);
  const text3Ref = useRef<HTMLHeadingElement>(null);
  const btnRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    const tl = gsap.timeline();

    tl.to(text1Ref.current, { opacity: 1, duration: 2, ease: "power2.inOut" })
      .to(text1Ref.current, { opacity: 0, duration: 1.5, ease: "power2.inOut", delay: 1 })
      
      .to(text2Ref.current, { opacity: 1, duration: 2, ease: "power2.inOut" })
      .to(text2Ref.current, { opacity: 0, duration: 1.5, ease: "power2.inOut", delay: 1 })
      
      .to(text3Ref.current, { opacity: 1, duration: 2, ease: "power2.inOut" })
      .to(btnRef.current, { opacity: 1, duration: 1.5, ease: "power2.inOut" }, "-=0.5");

    return () => {
      tl.kill();
    };
  }, []);

  const handleFinish = () => {
    gsap.to(containerRef.current, {
      opacity: 0,
      duration: 1,
      onComplete: onComplete
    });
  };

  return (
    <div ref={containerRef} className="fixed inset-0 z-50 flex items-center justify-center bg-midnight text-warm-ivory flex-col text-center px-4">
      <div className="absolute inset-0 bg-[url('/noise.png')] opacity-10 mix-blend-overlay pointer-events-none"></div>
      
      <div className="relative z-10 flex flex-col items-center justify-center min-h-[50vh]">
        <h1 ref={text1Ref} className="opacity-0 absolute text-2xl md:text-4xl font-light tracking-wide">
          {siteConfig.intro.line1}
        </h1>
        
        <h1 ref={text2Ref} className="opacity-0 absolute text-2xl md:text-4xl font-light tracking-wide text-dusty-rose">
          {siteConfig.intro.line2}
        </h1>
        
        <h1 ref={text3Ref} className="opacity-0 absolute text-lg md:text-2xl font-serif italic text-muted-gold">
          {siteConfig.intro.line3}
        </h1>
      </div>

      <button 
        ref={btnRef} 
        onClick={handleFinish}
        className="opacity-0 absolute bottom-20 mt-12 px-8 py-3 border border-warm-ivory/30 rounded-full hover:bg-warm-ivory/10 transition-colors uppercase tracking-widest text-sm"
      >
        {siteConfig.intro.buttonText}
      </button>
    </div>
  );
}
